export function parseStripInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedStripInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 15,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      depositor: getNextAccount(),
      authority: getNextAccount(),
      vault: getNextAccount(),
      sySrc: getNextAccount(),
      escrowSy: getNextAccount(),
      ytDst: getNextAccount(),
      ptDst: getNextAccount(),
      mintYt: getNextAccount(),
      mintPt: getNextAccount(),
      tokenProgram: getNextAccount(),
      addressLookupTable: getNextAccount(),
      syProgram: getNextAccount(),
      yieldPosition: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getStripInstructionDataDecoder().decode(instruction.data),
  };
}
